mapper.select:
SELECT chunk_id
FROM law_api_document_chunks
WHERE document_id = #{documentId}

SELECT chunk_id FROM law_api_document_chunks
WHERE document_id = #{documentId} AND chunk_version = #{chunkVersion}
ORDER BY chunk_id

SELECT COALESCE(MAX(chunk_version), 0) + 1
FROM law_api_document_chunk_versions
WHERE document_id = #{documentId}

mapper.update:
UPDATE law_api_document_chunk_versions
SET activation_status = 'CANDIDATE', activation_owner = NULL, updated_at = NOW()
WHERE document_id = #{documentId} AND chunk_version = #{chunkVersion}
  AND activation_status = 'ACTIVATING' AND activation_owner = #{owner}

UPDATE law_api_document_chunk_versions
SET activation_status = #{activationStatus}, activation_owner = NULL, updated_at = NOW()
WHERE document_id = #{documentId} AND chunk_version = #{chunkVersion}
  AND activation_status = 'ACTIVATING' AND activation_owner = #{owner}

mapper.select:
SELECT c.chunk_id AS chunkId, c.document_id AS documentId, doc.target AS target, doc.external_id AS externalId, doc.title AS title, doc.agency_name AS agencyName, doc.category_name AS categoryName, doc.source_date AS sourceDate, doc.effective_status AS effectiveStatus, c.chunk_no AS chunkNo, c.chunk_title AS chunkTitle, c.chunk_text AS chunkText, NULL AS pageNo, c.source_path AS sourcePath, c.source_url AS sourceUrl, c.sort_order AS sortOrder, c.content_hash AS contentHash, AS parentSectionTitle, AS sectionType, c.embedding_text AS embeddingText, c.parent_key AS parentKey, c.chunk_version AS chunkVersion FROM law_api_document_chunks c JOIN law_api_documents doc ON doc.document_id = c.document_id LEFT JOIN law_api_chunk_embeddings e ON e.chunk_id = c.chunk_id AND e.embedding_model = #{model} AND e.vector_store = #{vectorStore} WHERE doc.use_yn = 'Y' AND c.use_yn = 'Y' AND c.activation_status = 'ACTIVE' AND (#{target} = '' OR doc.target = #{target}) AND c.document_id IN
#{documentId}
AND ( e.chunk_id IS NULL OR e.status IN ('PENDING', 'NO_EMBED', 'FAILED', 'ERROR') OR COALESCE(e.content_hash, '') != COALESCE(c.content_hash, '') ) ORDER BY doc.target, c.document_id, c.sort_order, c.chunk_id LIMIT #{limit}

SELECT c.chunk_id AS chunkId, c.document_id AS documentId, doc.target AS target, doc.external_id AS externalId, doc.title AS title, doc.agency_name AS agencyName, doc.category_name AS categoryName, doc.source_date AS sourceDate, doc.effective_status AS effectiveStatus, c.chunk_no AS chunkNo, c.chunk_title AS chunkTitle, c.chunk_text AS chunkText, NULL AS pageNo, c.source_path AS sourcePath, c.source_url AS sourceUrl, c.sort_order AS sortOrder, c.content_hash AS contentHash, AS parentSectionTitle, AS sectionType, NULL AS embeddingText, c.parent_key AS parentKey, c.chunk_version AS chunkVersion FROM law_api_document_chunks c JOIN law_api_documents doc ON doc.document_id = c.document_id WHERE doc.use_yn = 'Y' AND c.use_yn = 'Y' AND c.activation_status = 'ACTIVE'
AND c.chunk_id IN
#{chunkId}

SELECT c.chunk_id AS chunkId, c.document_id AS documentId, doc.target AS target, doc.external_id AS externalId, doc.title AS title, doc.agency_name AS agencyName, doc.category_name AS categoryName, doc.source_date AS sourceDate, doc.effective_status AS effectiveStatus, c.chunk_no AS chunkNo, c.chunk_title AS chunkTitle, c.chunk_text AS chunkText, NULL AS pageNo, c.source_path AS sourcePath, c.source_url AS sourceUrl, c.sort_order AS sortOrder, c.content_hash AS contentHash, AS parentSectionTitle, AS sectionType, NULL AS embeddingText, c.parent_key AS parentKey, c.chunk_version AS chunkVersion FROM law_api_document_chunks c JOIN law_api_documents doc ON doc.document_id = c.document_id WHERE doc.use_yn = 'Y' AND c.use_yn = 'Y' AND c.activation_status = 'ACTIVE'
AND doc.target IN
#{target}
AND (
c.chunk_text LIKE CONCAT('%', #{keyword}, '%') OR c.chunk_title LIKE CONCAT('%', #{keyword}, '%') OR doc.title LIKE CONCAT('%', #{keyword}, '%')
)
ORDER BY (
(CASE WHEN c.chunk_title LIKE CONCAT('%', #{keyword}, '%') THEN 4 ELSE 0 END) + (CASE WHEN c.chunk_text LIKE CONCAT('%', #{keyword}, '%') THEN 3 ELSE 0 END) + (CASE WHEN doc.title LIKE CONCAT('%', #{keyword}, '%') THEN 1 ELSE 0 END)
) DESC, CASE
WHEN c.chunk_title LIKE CONCAT('%', #{keyword}, '%') THEN 0 WHEN doc.title LIKE CONCAT('%', #{keyword}, '%') THEN 1 WHEN c.chunk_text LIKE CONCAT('%', #{keyword}, '%') THEN 2
ELSE 3 END, CASE doc.target WHEN 'law' THEN 0 WHEN 'admrul' THEN 1 ELSE 2 END, doc.title, c.sort_order LIMIT #{limit}

SELECT c.chunk_id AS chunkId, c.document_id AS documentId, doc.target AS target, doc.external_id AS externalId, doc.title AS title, doc.agency_name AS agencyName, doc.category_name AS categoryName, doc.source_date AS sourceDate, doc.effective_status AS effectiveStatus, c.chunk_no AS chunkNo, c.chunk_title AS chunkTitle, c.chunk_text AS chunkText, NULL AS pageNo, c.source_path AS sourcePath, c.source_url AS sourceUrl, c.sort_order AS sortOrder, c.content_hash AS contentHash, AS parentSectionTitle, AS sectionType, c.embedding_text AS embeddingText, c.parent_key AS parentKey, c.chunk_version AS chunkVersion FROM law_api_document_chunks c JOIN law_api_documents doc ON doc.document_id = c.document_id WHERE doc.use_yn = 'Y' AND c.use_yn = 'Y' AND c.activation_status = 'ACTIVE'
AND doc.target IN
#{target}
AND (
c.chunk_title LIKE CONCAT('%', #{keyword}, '%') OR doc.title LIKE CONCAT('%', #{keyword}, '%')
)
ORDER BY (
(CASE WHEN c.chunk_title = #{keyword} THEN 9 ELSE 0 END) + (CASE WHEN c.chunk_title LIKE CONCAT(#{keyword}, '%') THEN 8 ELSE 0 END) + (CASE WHEN c.chunk_title LIKE CONCAT('%', #{keyword}, '%') THEN 7 ELSE 0 END) + (CASE WHEN doc.title = #{keyword} THEN 6 ELSE 0 END) + (CASE WHEN doc.title LIKE CONCAT(#{keyword}, '%') THEN 5 ELSE 0 END) + (CASE WHEN doc.title LIKE CONCAT('%', #{keyword}, '%') THEN 4 ELSE 0 END)
) DESC, CASE doc.target WHEN 'law' THEN 0 WHEN 'admrul' THEN 1 ELSE 2 END, doc.title, c.sort_order LIMIT #{limit}

SELECT c.chunk_id AS chunkId, c.document_id AS documentId, doc.target AS target, doc.external_id AS externalId, doc.title AS title, doc.agency_name AS agencyName, doc.category_name AS categoryName, doc.source_date AS sourceDate, doc.effective_status AS effectiveStatus, c.chunk_no AS chunkNo, c.chunk_title AS chunkTitle, c.chunk_text AS chunkText, NULL AS pageNo, c.source_path AS sourcePath, c.source_url AS sourceUrl, c.sort_order AS sortOrder, c.content_hash AS contentHash, AS parentSectionTitle, AS sectionType, NULL AS embeddingText, c.parent_key AS parentKey, c.chunk_version AS chunkVersion FROM ( SELECT doc.document_id, doc.target, doc.external_id, doc.title, doc.agency_name, doc.category_name, doc.source_date, doc.effective_status FROM law_api_documents doc WHERE doc.use_yn = 'Y'
AND doc.target IN
#{target}
AND (
doc.title LIKE CONCAT('%', #{keyword}, '%')
)
ORDER BY (
(CASE WHEN doc.title = #{keyword} THEN 8 ELSE 0 END) + (CASE WHEN doc.title LIKE CONCAT(#{keyword}, '%') THEN 5 ELSE 0 END) + (CASE WHEN doc.title LIKE CONCAT('%', #{keyword}, '%') THEN 3 ELSE 0 END)
) DESC, doc.target, doc.title LIMIT #{limit} ) doc JOIN law_api_document_chunks c ON c.document_id = doc.document_id WHERE c.use_yn = 'Y' AND c.activation_status = 'ACTIVE'
AND doc.target IN
#{target}
AND (
doc.title LIKE CONCAT('%', #{keyword}, '%')
)
ORDER BY CASE
WHEN doc.title = #{keyword} THEN 0 WHEN doc.title LIKE CONCAT(#{keyword}, '%') THEN 1 WHEN doc.title LIKE CONCAT('%', #{keyword}, '%') THEN 2
ELSE 3 END, doc.target, doc.title, c.sort_order LIMIT #{limit}

SELECT c.chunk_id AS chunkId, c.document_id AS documentId, doc.target AS target, doc.external_id AS externalId, doc.title AS title, doc.agency_name AS agencyName, doc.category_name AS categoryName, doc.source_date AS sourceDate, doc.effective_status AS effectiveStatus, c.chunk_no AS chunkNo, c.chunk_title AS chunkTitle, c.chunk_text AS chunkText, NULL AS pageNo, c.source_path AS sourcePath, c.source_url AS sourceUrl, c.sort_order AS sortOrder, c.content_hash AS contentHash, AS parentSectionTitle, AS sectionType, NULL AS embeddingText, c.parent_key AS parentKey, c.chunk_version AS chunkVersion FROM ( SELECT doc.document_id, doc.target, doc.external_id, doc.title, doc.agency_name, doc.category_name, doc.source_date, doc.effective_status FROM law_api_documents doc WHERE doc.use_yn = 'Y'
AND doc.target IN
#{target}
AND (
doc.title LIKE CONCAT('%', #{keyword}, '%')
)
ORDER BY (
(CASE WHEN doc.title = #{keyword} THEN 8 ELSE 0 END) + (CASE WHEN doc.title LIKE CONCAT(#{keyword}, '%') THEN 5 ELSE 0 END) + (CASE WHEN doc.title LIKE CONCAT('%', #{keyword}, '%') THEN 3 ELSE 0 END)
) DESC, doc.target, doc.title LIMIT #{limit} ) doc JOIN law_api_document_chunks c ON c.document_id = doc.document_id WHERE c.use_yn = 'Y'
AND doc.target IN
#{target}
AND (
doc.title LIKE CONCAT('%', #{keyword}, '%')
)
AND (
c.chunk_text LIKE CONCAT('%', #{keyword}, '%') OR c.chunk_title LIKE CONCAT('%', #{keyword}, '%')
)
ORDER BY (
(CASE WHEN c.chunk_text LIKE CONCAT('%', #{keyword}, '%') THEN 5 ELSE 0 END) + (CASE WHEN c.chunk_title LIKE CONCAT('%', #{keyword}, '%') THEN 3 ELSE 0 END)
) DESC, (
(CASE WHEN doc.title = #{keyword} THEN 8 ELSE 0 END) + (CASE WHEN doc.title LIKE CONCAT(#{keyword}, '%') THEN 5 ELSE 0 END) + (CASE WHEN doc.title LIKE CONCAT('%', #{keyword}, '%') THEN 3 ELSE 0 END)
) DESC, doc.target, doc.title, c.sort_order LIMIT #{limit}
